function extractTextFromHtml(html) {
    if (!html) return '';
    return html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

function extractBusinessInfo(html) {
    if (!html) return {};

    const result = {};

    const businessNameMatch = html.match(/<span class="bizname"[^>]*>(.*?)<\/span>/);
    if (businessNameMatch) {
        result.businessName = extractTextFromHtml(businessNameMatch[1]);
    }

    const addressMatch = html.match(/<span class="center-block"[^>]*>.*?<\/i>(.*?)<\/span>/);
    if (addressMatch) {
        result.address = extractTextFromHtml(addressMatch[1]);
    }

    const ratingMatch = html.match(/title="([^"]*out of 5)"/);
    if (ratingMatch) {
        result.rating = ratingMatch[1];
    }

    const reviewMatch = html.match(/\((\d+)\s*Reviews?\)/i);
    if (reviewMatch) {
        result.reviews = reviewMatch[1];
    }

    return result;
}

function extractCompetitorInfo(html) {
    if (!html) return {};

    const result = {};

    const businessNameMatch = html.match(/<a[^>]*title="[^"]*"[^>]*>(.*?)<\/a>/);
    if (businessNameMatch) {
        result.businessName = extractTextFromHtml(businessNameMatch[1]);
    }

    const ratingMatch = html.match(/title="([^"]*out of 5)"/);
    if (ratingMatch) {
        result.rating = ratingMatch[1];
    }

    const reviewMatch = html.match(/\((\d+)\)/);
    if (reviewMatch) {
        result.reviews = reviewMatch[1];
    }

    const addressMatch = html.match(/<span class="center-block"[^>]*>.*?<\/i>(.*?)<\/span>/);
    if (addressMatch) {
        result.address = extractTextFromHtml(addressMatch[1]);
    }

    const categoryMatch = html.match(/<strong title="primary category"[^>]*>(.*?)<\/strong>/);
    if (categoryMatch) {
        result.category = extractTextFromHtml(categoryMatch[1]);
    }

    const websiteMatch = html.match(/<a href="\/\/([^"]*)"[^>]*>([^<]*)<\/a>/);
    if (websiteMatch) {
        result.website = extractTextFromHtml(websiteMatch[2]);
    }

    const photoMatch = html.match(/<i class="fa fa-fw fa-photo"[^>]*><\/i>(\d+)/);
    if (photoMatch) {
        result.photos = photoMatch[1];
    }

    result.claimed = html.includes('Claimed') ? 'Evet' : 'Hayır';

    return result;
}

function main() {
    try {
        const inputData = $input.all()[0].json;

        const extractedData = {
            scan_information: [],
            rank_summary: [],
            top_competitors: [],
            sponsored_listings: []
        };

        // Scan Information işle
        if (inputData.scan_information_html) {
            const businessInfo = extractBusinessInfo(inputData.scan_information_html);

            if (businessInfo.businessName) {
                extractedData.scan_information.push({
                    'Özellik': 'İşletme Adı',
                    'Değer': businessInfo.businessName
                });
            }

            if (businessInfo.address) {
                extractedData.scan_information.push({
                    'Özellik': 'Adres',
                    'Değer': businessInfo.address
                });
            }

            if (businessInfo.rating) {
                extractedData.scan_information.push({
                    'Özellik': 'Puan',
                    'Değer': businessInfo.rating
                });
            }

            if (businessInfo.reviews) {
                extractedData.scan_information.push({
                    'Özellik': 'Yorum Sayısı',
                    'Değer': businessInfo.reviews
                });
            }

            // Keyword ve Date bilgilerini çıkar
            const keywordMatch = inputData.scan_information_html.match(/<td>Keyword<\/td>\s*<td[^>]*>(.*?)<\/td>/s);
            if (keywordMatch) {
                const keywordText = extractTextFromHtml(keywordMatch[1]);
                extractedData.scan_information.push({
                    'Özellik': 'Keyword',
                    'Değer': keywordText
                });
            }

            const dateMatch = inputData.scan_information_html.match(/<td>Date<\/td>\s*<td[^>]*>(.*?)<\/td>/s);
            if (dateMatch) {
                const dateText = extractTextFromHtml(dateMatch[1]);
                extractedData.scan_information.push({
                    'Özellik': 'Date',
                    'Değer': dateText
                });
            }
        }

        // Rank Summary işle
        if (inputData.rank_summary_html) {
            const rankMatches = inputData.rank_summary_html.matchAll(/<td[^>]*>(.*?)<\/td>\s*<td[^>]*>(.*?)<\/td>/gs);

            for (const match of rankMatches) {
                const metric = extractTextFromHtml(match[1]);
                const value = extractTextFromHtml(match[2]);

                if (metric && value) {
                    extractedData.rank_summary.push({
                        'Metrik': metric,
                        'Değer': value
                    });
                }
            }
        }

        // Top Competitors işle
        if (inputData.top_competitors_html) {
            const competitorRows = inputData.top_competitors_html.split('<tr class=');

            competitorRows.forEach((row, rowIndex) => {
                if (rowIndex === 0) return; // İlk element boş

                const rankMatch = row.match(/<td[^>]*>(\d+)<\/td>/);
                if (!rankMatch) return;

                const rank = rankMatch[1];
                const competitorInfo = extractCompetitorInfo(row);

                const foundAtMatch = row.match(/<h5[^>]*>\s*(\d+)\s*<\/h5>/);
                const foundAt = foundAtMatch ? foundAtMatch[1] : '';

                const avgRankMatch = row.match(/<span class="dotlg2[^"]*">([^<]*)<\/span>/);
                const avgRank = avgRankMatch ? avgRankMatch[1] : '';

                extractedData.top_competitors.push({
                    'Sıra': rank,
                    'İşletme Adı': competitorInfo.businessName || '',
                    'Puan': competitorInfo.rating || '',
                    'Yorum Sayısı': competitorInfo.reviews || '',
                    'Adres': competitorInfo.address || '',
                    'Kategori': competitorInfo.category || '',
                    'Website': competitorInfo.website || '',
                    'Fotoğraf Sayısı': competitorInfo.photos || '',
                    'Claimed': competitorInfo.claimed || 'Hayır',
                    'Bulunduğu Lokasyon': foundAt,
                    'Ortalama Sıra': avgRank
                });
            });
        }

        // Sponsored Listings işle
        if (inputData.sponsored_listings_html) {
            const sponsoredRows = inputData.sponsored_listings_html.split('<tr class=');

            sponsoredRows.forEach((row, rowIndex) => {
                if (rowIndex === 0) return;

                const rankMatch = row.match(/<td[^>]*>(\d+)<\/td>/);
                if (!rankMatch) return;

                const rank = rankMatch[1];
                const sponsoredInfo = extractCompetitorInfo(row);

                const appearedMatch = row.match(/Appeared in <strong>(\d+)<\/strong> searches/);
                const appeared = appearedMatch ? `Appeared in ${appearedMatch[1]} searches` : '';

                extractedData.sponsored_listings.push({
                    'Sıra': rank,
                    'İşletme Adı': sponsoredInfo.businessName || '',
                    'Puan': sponsoredInfo.rating || '',
                    'Yorum Sayısı': sponsoredInfo.reviews || '',
                    'Website': sponsoredInfo.website || '',
                    'Göründüğü Arama': appeared
                });
            });
        }

        return {
            json: {
                success: true,
                message: 'HTML veriler başarıyla işlendi',
                data: extractedData,
                processedAt: new Date().toISOString()
            }
        };

    } catch (error) {
        return {
            json: {
                success: false,
                error: error.message,
                stack: error.stack
            }
        };
    }
}

return main();

function parseCityFromAddress(address) {
    if (!address) return '';
    const addr = address.replace(/\s+/g, ' ').trim();
    const plzCityMatch = addr.match(/\b\d{5}\b\s*([^,]+?)(?=,|$)/i);
    if (plzCityMatch && plzCityMatch[1]) {
        const cityFromPlz = plzCityMatch[1].trim();
        const isStreetLike = /\d/.test(cityFromPlz) || /\b(str|straße|strasse|weg|platz|allee|gasse|ring)\b/i.test(cityFromPlz);
        if (!isStreetLike) return cityFromPlz;
    }
    const parts = addr.split(',').map(p => p.trim()).filter(Boolean);
    if (parts.length >= 2) {
        const last = parts[parts.length - 1] || '';
        const countryLike = /^(deutschland|germany)$/i.test(last);
        const candidate = (countryLike && parts.length >= 2) ? parts[parts.length - 2] : last;
        let cityCandidate = candidate.replace(/^\d{5}\s*/, '').trim();
        const isStreetLike = /\d/.test(cityCandidate) || /\b(str|straße|strasse|weg|platz|allee|gasse|ring)\b/i.test(cityCandidate);
        if (!isStreetLike && cityCandidate.length > 0) return cityCandidate;
    }
    return '';
}

function main() {
    try {
        // Node'lara direkt referans
        const companyNode = $('Current  Company').first().json;
        const scraperNode = $('Verileri Regex ile Ayrıştır').first().json;

        // Şirket bilgileri
        let isletmeAdi = companyNode['İşletme Adı'] || '';
        let isletmeAdresi = companyNode['İşletme Adresi'] || '';
        let sehir = companyNode['Şehir'] || parseCityFromAddress(isletmeAdresi);
        let yoneticiAdi = companyNode['Yönetici Adı'] || '';
        let yoneticiCinsiyet = companyNode['Yönetici Cinsiyeti'] || '';
        let reportUrl = companyNode['Report'] || '';

        // Scraper bilgileri
        const data = scraperNode.data || scraperNode;
        let keyword = '';
        let date = '';

        // Scan bilgilerini çıkar
        if (data.scan_information) {
            data.scan_information.forEach(item => {
                switch(item['Özellik']) {
                    case 'İşletme Adı':
                        if (!isletmeAdi) isletmeAdi = item['Değer'] || '';
                        break;
                    case 'Adres':
                        if (!isletmeAdresi) {
                            isletmeAdresi = item['Değer'] || '';
                            if (!sehir && isletmeAdresi) {
                                const adresParts = isletmeAdresi.split(',');
                                if (adresParts.length > 0) {
                                    sehir = adresParts[adresParts.length - 1].trim();
                                }
                            }
                        }
                        break;
                    case 'Keyword':
                        keyword = item['Değer'] || '';
                        break;
                    case 'Date':
                        date = item['Değer'] || '';
                        break;
                }
            });
        }

        // Kategori bilgisi
        let category = '';
        let categoryTranslate = '';
        if (keyword.includes('|')) {
            category = keyword.split('|')[0].trim();
            const translations = {
                'Immobilienmakler': 'Emlakçı',
                'Immobilienagentur': 'Emlak Acentesi', 
                'Immobilienberater': 'Emlak Danışmanı',
                'Immobilienverwaltung': 'Emlak Yönetimi'
            };
            categoryTranslate = translations[category] || 'Emlakçı';
        }

        // Sıralama özet bilgileri
        let rankedLocations = 0;
        let totalLocations = 25;
        let averageRank = 0;
        let bestRank = 0;

        if (data.rank_summary) {
            data.rank_summary.forEach(item => {
                const metrik = item['Metrik'] || '';
                const deger = item['Değer'] || '';

                switch(metrik) {
                    case 'Ranked Locations':
                        if (deger.includes(' / ')) {
                            const parts = deger.split(' / ');
                            rankedLocations = parseInt(parts[0].trim()) || 0;
                            totalLocations = parseInt(parts[1].trim()) || 25;
                        }
                        break;
                    case 'Average rank':
                        averageRank = parseFloat(deger) || 0;
                        break;
                    case 'Best rank':
                        bestRank = parseInt(deger) || 0;
                        break;
                }
            });
        }

        // İşletmenin görünürlüğü
        const isletmeGorunurluk = totalLocations > 0 ? Math.round((rankedLocations / totalLocations) * 100) : 0;

        // Top Competitors'ı AR skoruna göre sırala
        let sortedCompetitors = [];
        let isletmeArSirasi = "20+";

        if (data.top_competitors && data.top_competitors.length > 0) {
            const competitorsWithScore = data.top_competitors.map(comp => ({
                ...comp,
                avgRankFloat: parseFloat(comp['Ortalama Sıra']) || 999
            }));

            sortedCompetitors = competitorsWithScore.sort((a, b) => a.avgRankFloat - b.avgRankFloat);

            if (averageRank > 0) {
                let pozisyon = 1;
                for (let i = 0; i < sortedCompetitors.length; i++) {
                    if (averageRank > sortedCompetitors[i].avgRankFloat) {
                        pozisyon++;
                    }
                }
                isletmeArSirasi = pozisyon <= 20 ? pozisyon.toString() : "20+";
            }
        }

        // En iyi 3 rakibi al
        let rakip1 = '', rakip2 = '', rakip3 = '';
        let rakip1Gorunurluk = 0, rakip2Gorunurluk = 0, rakip3Gorunurluk = 0;
        let rakip1GorummeAdedi = '0', rakip2GorummeAdedi = '0', rakip3GorummeAdedi = '0';
        let rakip1OrtalamaSira = '0', rakip2OrtalamaSira = '0', rakip3OrtalamaSira = '0';

        if (sortedCompetitors.length > 0) {
            // Rakip 1
            if (sortedCompetitors[0]) {
                const r1 = sortedCompetitors[0];
                rakip1 = r1['İşletme Adı'] || '';
                rakip1GorummeAdedi = r1['Bulunduğu Lokasyon'] || '0';
                rakip1OrtalamaSira = r1['Ortalama Sıra'] || '0';
                const r1Lokasyon = parseInt(rakip1GorummeAdedi) || 0;
                rakip1Gorunurluk = Math.round((r1Lokasyon / 25) * 100);
            }

            // Rakip 2
            if (sortedCompetitors[1]) {
                const r2 = sortedCompetitors[1];
                rakip2 = r2['İşletme Adı'] || '';
                rakip2GorummeAdedi = r2['Bulunduğu Lokasyon'] || '0';
                rakip2OrtalamaSira = r2['Ortalama Sıra'] || '0';
                const r2Lokasyon = parseInt(rakip2GorummeAdedi) || 0;
                rakip2Gorunurluk = Math.round((r2Lokasyon / 25) * 100);
            }

            // Rakip 3
            if (sortedCompetitors[2]) {
                const r3 = sortedCompetitors[2];
                rakip3 = r3['İşletme Adı'] || '';
                rakip3GorummeAdedi = r3['Bulunduğu Lokasyon'] || '0';
                rakip3OrtalamaSira = r3['Ortalama Sıra'] || '0';
                const r3Lokasyon = parseInt(rakip3GorummeAdedi) || 0;
                rakip3Gorunurluk = Math.round((r3Lokasyon / 25) * 100);
            }
        }

        // Rakipler string'i
        const rakipler = [rakip1, rakip2, rakip3].filter(r => r).join(', ');

        // Görünürlük farkı
        const gorunurlukFarkSayi = 100 - isletmeGorunurluk;
        const gorunurlukFark = gorunurlukFarkSayi + '%';

        // Competitor report URL'si
        let competitorReportUrl = '';
        if (reportUrl) {
            competitorReportUrl = reportUrl.replace('/scan/', '/scans/competitors/');
        }

        // Final result objesi
        const resultObj = {
            ...companyNode,
            'id': companyNode.id || '',
            'İşletme Adı': isletmeAdi,
            'Yönetici Adı': yoneticiAdi,
            'Yönetici Cinsiyeti': yoneticiCinsiyet,
            'category': category,
            'Category Translate': categoryTranslate,
            'Report': reportUrl,
            "Competitor's Report": competitorReportUrl,
            'İşletmenin Görünürlük': isletmeGorunurluk + '%',
            'Görünürlük FARK': gorunurlukFark,
            'İşletmenin Görünme Adedi': rankedLocations.toString(),
            'İşletmenin Ortalama Sırası': averageRank.toString(),
            'İşletme AR Sırası': isletmeArSirasi,
            'Rakip 1': rakip1,
            'Rakip 2': rakip2,
            'Rakip 3': rakip3,
            'rakipler': rakipler,
            'Rakip 1 Görünürlük': rakip1Gorunurluk + '%',
            'Rakip 1 Görünme Adedi': rakip1GorummeAdedi,
            'Rakip 1 Ortalama Sıra': rakip1OrtalamaSira,
            'Rakip 2 Görünürlük': rakip2Gorunurluk + '%',
            'Rakip 2 Görünme Adedi': rakip2GorummeAdedi,
            'Rakip 2 Ortalama Sıra': rakip2OrtalamaSira,
            'Rakip 3 Görünürlük': rakip3Gorunurluk + '%',
            'Rakip 3 Görünme Adedi': rakip3GorummeAdedi,
            'Rakip 3 Ortalama Sıra': rakip3OrtalamaSira,


        };

        return [{
            json: resultObj
        }];

    } catch (error) {
        return [{
            json: {
                'Error': error.message,
                'Stack': error.stack,
                'Timestamp': new Date().toISOString()
            }
        }];
    }
}

return main();

const items = $input.all();

// Processed alanı 0 olan VE Report alanı boş olmayan + geçerli URL içeren kayıtları filtrele
const filtered = items.filter(item => {
    // Processed kontrol
    const isNotProcessed = item.json.Processed === 0 || item.json.Processed === "0"  ||  item.json.Processed === "null" ||  item.json.Processed === "" ;

    // Report URL kontrolü
    const hasValidReport = item.json.Report &&
                          item.json.Report.trim() !== "" &&
                          item.json.Report.includes('local-rank.report');

    // Her iki koşul da sağlanmalı
    return isNotProcessed && hasValidReport;
});

// Filtrelenmiş sonuçlardan ilk 20 kaydı al
const first20 = filtered.slice(0, 20);

return first20;
